export const clipClock=t=>'00:'+Math.floor(t).toString().padStart(2,'0');
export function pitchsideStory(input={}){
 const language=['en','es','pt'].includes(input.language)?input.language:'en',mode=['fan','beginner','math','analyst','player'].includes(input.mode)?input.mode:'fan',time=Math.max(0,Math.min(8,Number(input.time)||0)),l=['en','es','pt'].indexOf(language),copy=localized[language];
 const evidence=PITCHSIDE_BEATS.filter(b=>b.second<=time).map(b=>({id:b.id,second:b.second,title:b.titles[l],observation:b.observations[l],record_type:'reviewed_frame'})),i=evidence.length-1,latest=evidence.at(-1);
 let title=latest?.title||copy.waiting,body=latest?.observation||copy.intro;
 if(latest&&['beginner','analyst','player'].includes(mode))body=copy[mode][i];
 if(mode==='math'){title=copy.mathTitle;body=copy.mathBody;}
 const f=n=>new Intl.NumberFormat(language,{maximumFractionDigits:2}).format(n);
 const interval=evidence.length>1?`${copy.gap}: ${f(latest.second)} − ${f(evidence.at(-2).second)} = ${f(latest.second-evidence.at(-2).second)} s. ${copy.gapNote}`:'';
 const equation=`${copy.progress}: ${f(time)} ÷ 8 × 100 ≈ ${Math.round(time/8*100)}%. ${interval} ${copy.speed}`;
 return {title,body,time,cutoff:time,clock:clipClock(time),language,mode,team:'neutral',revision:1,complete:time>=7.95,resolved:!!latest,evidence,guideDefinition:copy.definition,copy,words:WORDS[language],equation,stats:`${evidence.length} / 4 · ${copy.stats}`,brief:{state:{seen:evidence},evidenceIds:evidence.map(e=>e.id)},review:{scope:'manually-reviewed-ai-video',limit:copy.limit},recap:evidence.map(e=>e.observation).join(' ')};
}
export function pitchsidePanel(packet){
 const {language,cutoff,copy,evidence,equation}=packet,ids=evidence.slice(-2).map(e=>e.id),story=mode=>pitchsideStory({time:cutoff,language,mode});
 return [
  {role:'analyst',summary:story('analyst').body,engine:'instant_notes'},
  {role:'guide',summary:copy.definition+' '+story('beginner').body,engine:'instant_notes'},
  {role:'math',summary:copy.mathBody,working:equation,engine:'calculated'},
  {role:'reviewer',summary:evidence.length?copy.check:copy.intro,engine:'evidence_rules'},
  {role:'presenter',summary:packet.body,engine:'instant_notes'}
 ].map(p=>({...p,title:packet.title,evidence_ids:ids,caution:copy.limit,cutoff,revision:1}));
}
export function pitchsideKey(input){return JSON.stringify([PITCHSIDE.id,PITCHSIDE.revision,Math.floor(Number(input.time)*10)/10,input.language,input.mode,(input.question||'').trim().replace(/\s+/g,' ')]);}
export function pitchsideExport(input,posts=[]){const p=pitchsideStory(input);return {schema:'btr.reviewed-video.v1',clip:PITCHSIDE,cutoff:p.cutoff,language:p.language,mode:p.mode,story:{title:p.title,body:p.body},evidence:p.evidence,calculations:p.equation,limits:p.copy.limit,public_contributions:posts,overlay:{start_seconds:p.cutoff,end_seconds:Math.min(8,p.cutoff+6),title:p.title,body:p.body,evidence_ids:p.evidence.map(e=>e.id)}};}
